package at.redeye.twelvelittlescoutsclerk.reports;

import java.util.Locale;
import org.odftoolkit.odfdom.doc.OdfSpreadsheetDocument;
import org.odftoolkit.odfdom.doc.table.OdfTable;
import org.odftoolkit.odfdom.doc.table.OdfTableCell;
import org.odftoolkit.odfdom.doc.table.OdfTableColumn;
import org.odftoolkit.odfdom.doc.table.OdfTableRow;
import org.odftoolkit.odfdom.dom.style.props.OdfTableCellProperties;
import org.odftoolkit.odfdom.dom.style.props.OdfTableColumnProperties;
import org.odftoolkit.odfdom.dom.style.props.OdfTextProperties;

/**
 * Small helper collection for writing ODS (LibreOffice Calc) documents with
 * odfdom 0.10.0. Copy into the report package and adapt the visibility as needed.
 *
 * Colour scheme used by the reports in this project:
 *  - section headers: medium blue background with bold black text (only fill in the sheet)
 *  - totals, balance line: bold only, no fill
 *  - negative values: dark red
 */
public final class OdsExportHelper {

    /** background colour for section header rows (the only coloured rows) */
    public static final String COLOR_HEADER = "#8ea9db";
    /** font colour for negative amounts */
    public static final String COLOR_NEGATIVE = "#c00000";

    private static final Locale MONEY_LOCALE = Locale.GERMANY;
    private static final String MONEY_FORMAT = "€ #,##0.00";

    private OdsExportHelper() {
    }

    /**
     * Creates a spreadsheet document and prepares the first sheet: name,
     * column count and print flag (the default sheet is not printable).
     *
     * @param firstSheetName name of the first sheet
     * @param columnCount    number of columns the first sheet must have
     * @return the new document (save it with {@code doc.save(fos)})
     */
    public static OdfSpreadsheetDocument createDocument(String firstSheetName, int columnCount) throws Exception {
        OdfSpreadsheetDocument doc = OdfSpreadsheetDocument.newSpreadsheetDocument();
        OdfTable table = doc.getSpreadsheetTables().get(0);
        table.setTableName(firstSheetName);
        table.getOdfElement().setTablePrintAttribute(true);
        ensureColumns(table, columnCount);
        return doc;
    }

    /** Returns the first sheet of a document created by {@link #createDocument(String, int)}. */
    public static OdfTable firstSheet(OdfSpreadsheetDocument doc) {
        return doc.getSpreadsheetTables().get(0);
    }

    /**
     * Returns the empty row a fresh sheet already contains.
     *
     * odfdom cannot remove the last remaining row of a sheet, therefore the
     * first report line reuses this row instead of clearing the sheet.
     */
    public static OdfTableRow getFirstRow(OdfTable table) {
        return table.getRowCount() > 0 ? table.getRowByIndex(0) : table.appendRow();
    }

    /** Grows the table so every row has at least {@code columnCount} cells. */
    public static void ensureColumns(OdfTable table, int columnCount) {
        if (table.getColumnCount() < columnCount) {
            table.appendColumns(columnCount - table.getColumnCount());
        }
    }

    /** Writes a text cell; empty values are skipped unless a style is requested. */
    public static void setText(OdfTableRow row, int column, String value, boolean bold, String background) {
        if ((value == null || value.isEmpty()) && !bold && background == null) {
            return;
        }
        OdfTableCell cell = row.getCellByIndex(column);
        cell.setStringValue(value != null ? value : "");
        style(cell, bold, background);
    }

    /**
     * Writes a numeric money cell. Zero values stay blank unless a style
     * (bold/background) is requested, e.g. for total rows. Negative values
     * are written in red.
     */
    public static void setMoney(OdfTableRow row, int column, double value, boolean bold, String background) {
        boolean hasValue = value != 0.0;
        if (!hasValue && !bold && background == null) {
            return;
        }
        OdfTableCell cell = row.getCellByIndex(column);
        if (hasValue) {
            cell.setDoubleValue(value);
            cell.setFormatString(MONEY_FORMAT);
            if (value < 0.0) {
                cell.getOdfElement().setProperty(OdfTextProperties.Color, COLOR_NEGATIVE);
            }
        }
        style(cell, bold, background);
    }

    /**
     * Applies bold and background. Both properties, together with the number
     * format and the font colour, end up in one automatic cell style.
     */
    private static void style(OdfTableCell cell, boolean bold, String background) {
        if (bold) {
            cell.getOdfElement().setProperty(OdfTextProperties.FontWeight, "bold");
        }
        if (background != null) {
            cell.getOdfElement().setProperty(OdfTableCellProperties.BackgroundColor, background);
        }
    }

    /**
     * Standard widths for a ledger sheet: 5 cm label column, 2.3 cm per month,
     * 2.8 cm for the sum column.
     */
    public static void setLedgerColumnWidths(OdfTable table, int monthCount) {
        String[] widths = new String[monthCount + 2];
        widths[0] = "5.0cm";
        for (int i = 1; i <= monthCount; i++) {
            widths[i] = "2.3cm";
        }
        widths[monthCount + 1] = "2.8cm";
        setColumnWidths(table, widths);
    }

    /**
     * Sets explicit column widths. setWidth() in odfdom 0.10.0 fails on locale
     * specific decimal values, and setUseOptimalWidth(true) is not recalculated
     * by LibreOffice on load, so the width is written as style property.
     */
    public static void setColumnWidths(OdfTable table, String[] widths) {
        for (int i = 0; i < table.getColumnCount() && i < widths.length; i++) {
            OdfTableColumn column = table.getColumnByIndex(i);
            if (column != null) {
                column.getOdfElement().setProperty(OdfTableColumnProperties.ColumnWidth, widths[i]);
            }
        }
    }

    /** German money formatting for text lines, e.g. "21.328,22". */
    public static String money(double value) {
        return String.format(MONEY_LOCALE, "%,.2f", value);
    }
}
